window.ScripturaLexicons.BDAG_PART_0326 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0326-01\" data-source=\"BDAG\" data-search=\"σκληροτράχηλος, ον adjetivo de dura cerviz; obstinado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκληροτράχηλος, ον</td><td>adjetivo</td><td>de dura cerviz; obstinado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0326-02\" data-source=\"BDAG\" data-search=\"σκληρύνω verbo endurecer; tornar-se endurecido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκληρύνω</td><td>verbo</td><td>endurecer; tornar-se endurecido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0326-03\" data-source=\"BDAG\" data-search=\"σκολιός, ά, όν adjetivo torto; perverso; desonesto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκολιός, ά, όν</td><td>adjetivo</td><td>torto; perverso; desonesto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0326-04\" data-source=\"BDAG\" data-search=\"σκολιότης, ητος, ἡ substantivo feminino perversidade; dolo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκολιότης, ητος, ἡ</td><td>substantivo feminino</td><td>perversidade; dolo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0326-05\" data-source=\"BDAG\" data-search=\"σκόλοψ, οπος, ὁ substantivo masculino espinho; farpa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκόλοψ, οπος, ὁ</td><td>substantivo masculino</td><td>espinho; farpa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0326-06\" data-source=\"BDAG\" data-search=\"σκοπέω verbo observar; prestar atenção; acautelar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκοπέω</td><td>verbo</td><td>observar; prestar atenção; acautelar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0326-07\" data-source=\"BDAG\" data-search=\"σκοπός, οῦ, ὁ substantivo masculino alvo; meta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκοπός, οῦ, ὁ</td><td>substantivo masculino</td><td>alvo; meta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0326-08\" data-source=\"BDAG\" data-search=\"σκορπίζω verbo dispersar; espalhar; distribuir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκορπίζω</td><td>verbo</td><td>dispersar; espalhar; distribuir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0326-09\" data-source=\"BDAG\" data-search=\"σκορπίος, ου, ὁ substantivo masculino escorpião BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκορπίος, ου, ὁ</td><td>substantivo masculino</td><td>escorpião</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0326-10\" data-source=\"BDAG\" data-search=\"σκορπισμός, οῦ, ὁ substantivo masculino dispersão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκορπισμός, οῦ, ὁ</td><td>substantivo masculino</td><td>dispersão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0326-11\" data-source=\"BDAG\" data-search=\"σκοτεινός, ή, όν adjetivo escuro; obscuro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκοτεινός, ή, όν</td><td>adjetivo</td><td>escuro; obscuro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0326-12\" data-source=\"BDAG\" data-search=\"σκοτία, ας, ἡ substantivo feminino escuridão; trevas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκοτία, ας, ἡ</td><td>substantivo feminino</td><td>escuridão; trevas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0326-13\" data-source=\"BDAG\" data-search=\"σκοτίζω verbo escurecer-se; obscurecer-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκοτίζω</td><td>verbo</td><td>escurecer-se; obscurecer-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0326-14\" data-source=\"BDAG\" data-search=\"σκότος, ους, τό substantivo neutro escuridão; trevas; portador de trevas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκότος, ους, τό</td><td>substantivo neutro</td><td>escuridão; trevas; portador de trevas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0326-15\" data-source=\"BDAG\" data-search=\"σκοτόω verbo escurecer-se; obscurecer-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκοτόω</td><td>verbo</td><td>escurecer-se; obscurecer-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0326-16\" data-source=\"BDAG\" data-search=\"σκύβαλον, ου, τό substantivo neutro refugo; lixo; excremento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκύβαλον, ου, τό</td><td>substantivo neutro</td><td>refugo; lixo; excremento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0326-17\" data-source=\"BDAG\" data-search=\"Σκύθης, ου, ὁ substantivo masculino; etnônimo cita BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σκύθης, ου, ὁ</td><td>substantivo masculino; etnônimo</td><td>cita</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0326-18\" data-source=\"BDAG\" data-search=\"σκυθρωπία, ας, ἡ substantivo feminino tristeza; abatimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκυθρωπία, ας, ἡ</td><td>substantivo feminino</td><td>tristeza; abatimento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0326-19\" data-source=\"BDAG\" data-search=\"σκυθρωπός adjetivo triste; sombrio; carrancudo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκυθρωπός</td><td>adjetivo</td><td>triste; sombrio; carrancudo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0326-20\" data-source=\"BDAG\" data-search=\"σκύλλω verbo fatigar; importunar; incomodar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σκύλλω</td><td>verbo</td><td>fatigar; importunar; incomodar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0326-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκληροτράχηλος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκληροτράχηλος</span>, <span class=\"greek\">ον</span> (uma formação correta, mas modelada segundo <span class=\"hebrew\">קְשֵׁה־עֹרֶף</span>; Aesop 318 H. [=S 30 P. p. 538 e H-H.]; Physiogn. I 368, 4, esta passagem e a de Esopo são produto da edição bizantina; LXX; En 98:11; ViDa 6 [p. 77, 11 Sch. <span class=\"greek\">τὸ</span> <span class=\"greek\">σκλ</span>.]; Mel., P. 17, 115 [<span class=\"greek\">Φαραώ</span>].—<span class=\"greek\">τράχηλος</span> <span class=\"greek\">σκληρός</span>: Hippocr., Coac. Progn. 2, 14, 256 ed. Littré; V p. 640) de dura cerviz, obstinado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.51\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:51</a>; 1 Cl 53:3 (Dt 9:13).—M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0326-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκληρύνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκληρύνω</span> fut. <span class=\"greek\">σκληρυνῶ</span>; 1 aor. <span class=\"greek\">ἐσκλήρυνα</span>. Pass.: imperf. <span class=\"greek\">ἐσκληρυνόμην</span>; 1 aor. <span class=\"greek\">ἐσκληρύνθην</span> (<span class=\"greek\">σκληρός</span>; Hippocr. et al.; Aristot., Galen; PLeid X II, 28; LXX; PsSol 8:29; TestSol 25:3, 5) prim. ‘endurecer’; em nossa lit. somente em sentido fig.: fazer com que alguém se torne inflexível na resistência à informação, endurecer (LXX)</p><p class=\"entry-text\">ⓐ at.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. com sujeito humano <span class=\"greek\">τὶ</span> algo <span class=\"greek\">τὴν</span> <span class=\"greek\">καρδίαν</span> 1 Cl 51:3a; <span class=\"greek\">τὰς</span> <span class=\"greek\">καρδίας</span> (Ps 94:8) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:8</a>, 15; 4:7. <span class=\"greek\">τὸν</span> <span class=\"greek\">τράχηλον</span> <span class=\"greek\">σκλ</span>. endurecer a cerviz B 9:5 (Dt 10:16).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. com Deus como suj. <span class=\"greek\">τινά</span> endurecer o coração de alguém (cf. Ex 7:3; 9:12 al.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:18</a>.—KSchmidt, D. Verstockung des Menschen durch Gott: TZ 1, ’45, 1–17.</p><p class=\"entry-text\">ⓑ pass. estar ou tornar-se endurecido (Sir 30:12) <span class=\"greek\">ἐσκληρύνοντο</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:9</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:13</a>. <span class=\"greek\">ἐσκληρύνθη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">καρδία</span> (cf. Ex 8:15; 9:35) 1 Cl 51:3b; cf. 5.—Sobre o modo helênico de exprimir este tema v. s.v. <span class=\"greek\">τίκτω</span>, fim.—DELG s.v. <span class=\"greek\">σκέλλομαι</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0326-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκολιός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκολιός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">σκέλος</span>; Hom. et al.; Kaibel 244, 4; LXX, Joseph.; SibOr 1, 124; prim. ‘curvo, dobrado’)</p><p class=\"entry-text\">① relativo a ser dobrado, curvo ou torto em oposição a reto, torto (op. <span class=\"greek\">εὐθύς</span>; cf. Jos., Bell. 3, 118 <span class=\"greek\">τὰ</span> <span class=\"greek\">σκολιὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">λεωφόρου</span> [=estrada principal] <span class=\"greek\">κατευθύνειν</span>) <span class=\"greek\">ἔσται</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">σκολιὰ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">εὐθεῖαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:5</a> (cf. escólio sobre Nicander, Ther. 478 a respeito de <span class=\"greek\">ὁδός</span> em contraste com <span class=\"greek\">εὐθύς</span>; Is 40:4; 42:16). Na imagem de <span class=\"greek\">τοῦ</span> <span class=\"greek\">μέλανος</span> <span class=\"greek\">ὁδός</span> B 20:1 (cf. Pr 21:8; 28:18).</p><p class=\"entry-text\">② relativo a ser moralmente torto ou deturpado, torto, inescrupuloso, desonesto, etc., extensão fig. de 1 (Hom. et al.; Dio Chrys. 58 [75], 1 com <span class=\"greek\">πονηρός</span>; Lucian, Bis Accus. 16 <span class=\"greek\">ῥημάτια</span>; LXX; Jos., C. Ap. 1, 179) <span class=\"greek\">γενεὰ</span> <span class=\"greek\">σκ</span>. (Dt 32:5 <span class=\"greek\">γεν</span>. <span class=\"greek\">σκ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">διεστραμμένη</span>; Ps 77:8. Também Dionysius Perieg. [GGM II 186 p. 127 v. 392 <span class=\"greek\">σκολιὸν</span> <span class=\"greek\">γένος</span>]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.40\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:40</a> (diversamente MWilcox, The Semitisms of Ac, ’65, 30); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:15</a>. <span class=\"greek\">δεσπόται</span> severos, injustos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:18</a> (op. <span class=\"greek\">ἀγαθοὶ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐπιεικεῖς</span>).—<span class=\"greek\">σκολιόν</span> <span class=\"greek\">τι</span> algo errado 1 Cl 39:4 (Job 4:18).—JPalache, Semantic Notes on the Hebrew Lexicon ’59, 55f. B. 897. DELG s.v. <span class=\"greek\">σκέλος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0326-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκολιότης, ητος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκολιότης</span>, <span class=\"greek\">ητος</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">σκολιός</span>; Hippocr.+; LXX, Aq., Sym.) fig. (Aristaen., Ep. 1, 28) tortuosidade, perversidade, dolo (Ezk 16:5 <span class=\"greek\">τῇ</span> <span class=\"greek\">σκολ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ψυχῆς</span> <span class=\"greek\">σου</span>) com <span class=\"greek\">πονηρία</span> Hv 3, 9, 1.—DELG s.v. <span class=\"greek\">σκέλος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0326-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκόλοψ, οπος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκόλοψ</span>, <span class=\"greek\">οπος</span>, <span class=\"greek\">ὁ</span> (Hom. et al.; Artem.; PGM 36, 152; 270; LXX) orig. ‘qualquer coisa pontiaguda’, como uma ‘estaca (pontiaguda)’, depois algo que causa grave incômodo, espinho, farpa, etc., especif. a respeito de um corpo estranho lesivo (SIG 1168, 92; Num 33:55 <span class=\"greek\">σκόλοπες</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὀφθαλμοῖς</span>; Sext. Emp. em BGU 380, 8 <span class=\"greek\">τὸν</span> <span class=\"greek\">πόδαν</span> <span class=\"greek\">πονεῖς</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">σκολάπου</span>; Aesop, Fab. 187 P.; 363 P.=Babrius n.º 136, 18 L-P.; Artem. 3, 33; Cyranides p. 112, 24 uma prescrição para remover <span class=\"greek\">σκόλοπας</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἀκάνθας</span>.—Field, Notes 187). Paulo alude à sua enfermidade (v. <span class=\"greek\">κολαφίζω</span> 2 e também EMerrins, St. Paul’s Thorn in the Flesh: BiblSacr 64, 1907, 661–92. Para diferentes pontos de vista v. CBruston, L’Écharde de St. Paul: RTQR 21, 1912, 441ff; PJoüon, RSR 15, 1925, 532f; CNash, Paul’s ‘Thorn in the Flesh’: RevExp 28, ’31, 33–51; PMenoud, Studia Paulina [JdeZwaan Festschr.] ’53, 163–71; HClavier, ibid. 66–82; TMullins, JBL 76, ’57, 299–303; AHisey e JBeck, Journ. of Bible and Religion 29, ’61, 125–29; JThierry, D. Dorn im Fleisch, NovT 5, ’62, 301–10; MBarré, CBQ 42, ’80, 216–27; VFurnish, II Corinthians (AB) ’84, 547–50; DPark, NovT 22, ’80, 179–83; UHeckel, ZNW 84, ’93, 65–92. A falta de pormenores impossibilita uma análise verdadeiramente científica do <span class=\"greek\">σκ</span>. de Paulo) em <span class=\"greek\">ἐδόθη</span> <span class=\"greek\">μοι</span> <span class=\"greek\">σκ</span>. <span class=\"greek\">τῇ</span> <span class=\"greek\">σαρκί</span> foi-me dado um espinho na carne <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:7</a>. O fato de Celso empregar a palavra <span class=\"greek\">σκ</span>. (2, 55; 68) com evidente desdém (Orígenes emprega <span class=\"greek\">σταυρός</span>) para designar a cruz de Jesus dificilmente pode indicar que Paulo a esteja empregando aqui nesse sentido, visto que sempre diz <span class=\"greek\">σταυρός</span> alhures (contra ASchlatter, Pls, d. Bote J. Chr. ’34, 666). Também Luciano, em Peregr. 13, 337, desdenhosamente a respeito de <span class=\"greek\">ἀνεσκολοπισμένος</span> <span class=\"greek\">ἐκεῖνος</span> <span class=\"greek\">σοφιστής</span>. Cf. 11, 334 <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">ἀνασκολοπισθείς</span>. Um crente não emprega esse tipo de linguagem.—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0326-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκοπέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκοπέω</span> (<span class=\"greek\">σκοπός</span>; Hom.+; inscr., pap.; Esth 8:12g; 2 Macc 4:5; TestNapth 3:1 v.l.; Philo, Joseph., Just.; Ath. 10, 2, R. 2 p. 49, 25 al.—B-D-F §101, p. 48; Mlt.-H. 258) part. fut. <span class=\"greek\">σκόπησον</span> (Just., D. 3, 2) prestar cuidadosa atenção a, estar atento a, observar, com ac. de pess. ou coisa, alguém ou algo (Jos., Ant. 12, 30; Just., D. 2, 5) <span class=\"greek\">σκοπεῖτε</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">οὕτω</span> <span class=\"greek\">περιπατοῦντας</span> observai os que assim se conduzem, i.e., a fim de imitá-los <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:17</a>. <span class=\"greek\">σκοπεῖν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">διχοστασίας</span> <span class=\"greek\">ποιοῦντας</span> estar atento aos que causam divisões, i.e., evitá-los <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:17</a>.—<span class=\"greek\">σκ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">βλεπόμενα</span> manter os olhos no que se pode ver <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:18</a>.—<span class=\"greek\">τὰ</span> <span class=\"greek\">ἑαυτῶν</span> cuidar dos próprios interesses (Pla., Phdr. 232d) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:4</a>. Também <span class=\"greek\">τὸ</span> <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἑαυτούς</span> MPol 1:2. <span class=\"greek\">τὸ</span> <span class=\"greek\">κοινὸν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐλπίδος</span> 1 Cl 51:1.—<span class=\"greek\">σκ</span>. <span class=\"greek\">ἑαυτόν</span> seguido de <span class=\"greek\">μή</span> acautelar-se para que … não <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:1</a>. <span class=\"greek\">σκόπει</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">σκότος</span> <span class=\"greek\">ἐστίν</span> considera se a luz é trevas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:35</a> (<span class=\"greek\">μή</span> interrog. = lat. ‘num’ [cf. Zahn ad loc.; diversamente Rob. 995] por causa do indic.; cf. Epict. 4, 5, 18 <span class=\"greek\">ὅρα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">Νερωνιανὸν</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">χαρακτῆρα</span>).—DELG s.v. <span class=\"greek\">σκέπτομαι</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0326-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκοπός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκοπός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (desde Hom. em vários sentidos) meta, alvo (Hom.+; inscr., pap.; Job 16:12; La 3:12; Wsd 5:12; TestJob 9:8; EpArist 251; Jos., Ant. 16, 248; Ath., R. 23 p. 77, 7) <span class=\"greek\">ὁ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">εἰρήνης</span> <span class=\"greek\">σκ</span>. 1 Cl 19:2; <span class=\"greek\">ὁ</span> <span class=\"greek\">προκείμενος</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">σκ</span>. 63:1 (Philo, Mos. 1, 48; Jos., Bell. 4, 555 <span class=\"greek\">σκοπὸς</span> <span class=\"greek\">προύκειτο</span> <span class=\"greek\">Ῥωμαίοις</span>). <span class=\"greek\">κατὰ</span> <span class=\"greek\">σκοπὸν</span> <span class=\"greek\">διώκειν</span> prosseguir rumo à meta (Paulo está ‘em pleno esforço de alcançar o alvo’; cf. <span class=\"greek\">κατὰ</span> <span class=\"greek\">σκόπον</span> <span class=\"greek\">ἐκτοξεύειν</span>=‘disparar diretamente no alvo’ Onosander 17; <span class=\"greek\">διώκω</span> 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:14</a>. <span class=\"greek\">σκοπὸν</span> <span class=\"greek\">τιθέναι</span> estabelecer um alvo (cf. Pla., Leg. 12, 961e; Polyb. 7, 8, 9) 2 Cl 19:1.—DLasky, An Examination of the Metaphorical Use of ‘Skopos’ or Target in the Philosophical Works of Plato and Aristotle through a Study of Archery Imagery in the Greek Literary Tradition, 2 vols. diss. Chicago ’94. DELG s.v. <span class=\"greek\">σκέπτομαι</span> B. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0326-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκορπίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκορπίζω</span> (de <span class=\"greek\">σκορπίος</span>) fut. <span class=\"greek\">σκορπιῶ</span> LXX; 1 aor. <span class=\"greek\">ἐσκόρπισα</span>. Pass.: fut. 3 pl. <span class=\"greek\">σκορπισθήσονται</span> Tob 14:4 BA; 1 aor. <span class=\"greek\">ἐσκορπίσθην</span>; part. perf. <span class=\"greek\">ἐσκορπισμένος</span> LXX.</p><p class=\"entry-text\">① fazer um grupo ou um conjunto ir em várias direções, espalhar, dispersar (Hecataeus Mil.: 1 Fgm. 366 Jac. [em Phryn. p. 218 Lob.]; Strabo 4, 4, 6; Ps.-Lucian, Asinus 32; Aelian, VH 13, 45; Jos., Ant. 16, 10; LXX; TestSol; TestAsh 7:6 v.l.; Tat. 30, 1), de um lobo, <span class=\"greek\">τὰ</span> <span class=\"greek\">πρόβατα</span> <span class=\"greek\">σκορπίζει</span> ele afugenta as ovelhas em todas as direções <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:12</a>. Op. <span class=\"greek\">συνάγειν</span> (Artem. 1, 56 p. 52, 17 <span class=\"greek\">συνάγει</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἐσκορπισμένους</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄργανον</span>; Tob 13:5 BA) <span class=\"greek\">ὁ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">συνάγων</span> <span class=\"greek\">μετ</span>’ <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">σκορπίζει</span>, prov. em ref. a um rebanho, e não a uma colheita <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:23</a> (em Astrampsychus 40 Dec. 83, 8 e Cat. Cod. Astr. II 162, 7 <span class=\"greek\">σκ</span>.=‘esbanjar, desperdiçar’.—Sobre a ideia v. Polyaenus 8, 23, 27: <span class=\"greek\">Καῖσαρ</span> <span class=\"greek\">Πομπηί̈ου</span> <span class=\"greek\">κηρύξαντος</span> <span class=\"greek\">ἔχθραν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">μηδετέρῳ</span> <span class=\"greek\">προστιθεμένοις</span> <span class=\"greek\">ἀντεκήρυξε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">φίλους</span> <span class=\"greek\">ἡγήσεσθαι</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἴσον</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">συμμαχήσασιν</span> ‘quando Pompeu declarou hostilidade, César, por sua vez, proclamou aos que não tomavam partido que os considerava amigos em pé de igualdade com os que se aliaram a ele’. Em lat. em Cícero: AFridrichsen, ZNW 13, 1012, 273–80. O ponto de vista de César assemelha-se ao de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:40</a>=<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.50\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:50</a>). Pass. (Plut., Timol. 4, 2; Philo; Jos., Ant. 6, 116; 1 Macc 6:54 <span class=\"greek\">ἐσκορπίσθησαν</span> <span class=\"greek\">ἕκαστος</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">αὐτοῦ</span>) ser dispersado <span class=\"greek\">ἵνα</span> <span class=\"greek\">σκορπισθῆτε</span> <span class=\"greek\">ἕκαστος</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἴδια</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:32</a>.</p><p class=\"entry-text\">② distribuir em várias direções, espalhar, distribuir (PLond I, 131, 421 p. 182 [I d.C.] a respeito de espalhar adubo por todo um campo; PFlor 175, 22 <span class=\"greek\">τὰ</span> <span class=\"greek\">καμήλια</span> <span class=\"greek\">ἐσκορπίσαμεν</span>=‘distribuímos os camelos em vários lugares’; Jos., Ant. 16, 10), de Deus, <span class=\"greek\">ἐσκόρπισεν</span>, <span class=\"greek\">ἔδωκεν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">πένησιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:9</a> (Ps 111:9).—DELG s.v. <span class=\"greek\">σκορπίος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0326-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκορπίος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκορπίος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Aeschyl., Pla. et al.; Sb 1209 <span class=\"greek\">ἐτελεύτησεν</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">σκορπίου</span>; 1267, 7; LXX; TestSol 13:8 P; Philo; Jos., Ant. 8, 217; Tat. 9, 2).</p><p class=\"entry-text\">① uma espécie de animal nocivo, escorpião (um aracnídeo, de 4 a 5 polegadas de comprimento), comum nas latitudes meridionais, muito temido por causa de sua picada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:3</a>, 5, 10 (<span class=\"greek\">κέντρον</span> como Demosth. 25, 52). Com serpentes (Dio Chrys. 57 [74], 20; Sb 6584, 6; Dt 8:15) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:19</a>; 11:12 (cf. <span class=\"greek\">ἀντί</span> 1. HPegg, ET 38, 1927, 468).</p><p class=\"entry-text\">② uma pessoa extremamente nociva, escorpião, extensão fig. de 1, de prostitutas <span class=\"greek\">ἔνδοθεν</span> <span class=\"greek\">πεπλήρωνται</span> <span class=\"greek\">σκορπίων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">ἀδικίας</span> Ox 840, 40 (metaf. de pessoas más em Ps.-Demosth. 25, 52; Artem. 2, 13 p. 107, 11 et al. V. também Ezk 2:6).—S. Eitrem, Der Sk. in Mythol. u. Religionsgesch.: SymbOsl 7, 1928, 53–82; Neugebauer/Hoesen índice p. 201.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0326-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκορπισμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκορπισμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">σκορπίζω</span>; M. Ant. 7, 50, 2; Artem. 2, 30 p. 126, 13; Hippiatr. 70, 6 [da dispersão do calor febril]; Cat. Cod. Astr. VIII/1, p. 268, 26 <span class=\"greek\">σκ</span>. <span class=\"greek\">χρημάτων</span>; Jer 25:34 Aq., Sym., Theod.; PsSol 17:18; Philo, Leg. All. 2, 86; SibOr 3, 317) dispersão <span class=\"greek\">σκ</span>. <span class=\"greek\">ὀστέων</span> dispersão dos ossos, prov. uma ref. específica à ação das feras que dilaceram a carne de Paulo; na imaginação desenfreada de Ign., uma das muitas torturas correlatas que acompanham o martírio, IRo 5:3.—DELG s.v. <span class=\"greek\">σκορπίος</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0326-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκοτεινός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκοτεινός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">σκότος</span>; Aeschyl. et al.; Cebes 10, 1; Cornutus 17, p. 29, 14; UPZ 78, 19 [159 a.C.] <span class=\"greek\">εἰς</span> <span class=\"greek\">σκοτινὸν</span> <span class=\"greek\">τόπον</span>; LXX; En, TestSol; Jos., Bell. 1, 77, Ant. 2, 344; Just., D. 17, 3; Mel., P. 24, 164 e 169.—W-H. <span class=\"greek\">σκοτινός</span> como En 22:2) escuro, op. <span class=\"greek\">φωτεινός</span> (cf. X., Mem. 3, 10, 1; 4, 3, 4; Plut., Mor. 610e; 953c; En 22:2): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:34</a>, 36 (cf. TestBenj 4:2 <span class=\"greek\">σκοτεινὸς</span> <span class=\"greek\">ὀφθαλμός</span>; Damasc., Vi. Isid. 92 <span class=\"greek\">τὸ</span> <span class=\"greek\">σκ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ὀφθαλμῶν</span>). Op. <span class=\"greek\">φανερός</span> obscuro B 8:7. <span class=\"greek\">νεφέλη</span> <span class=\"greek\">σκ</span>. nuvem escura GJs 19:2 (cf. Ex 19:16 <span class=\"greek\">νεφέλη</span> <span class=\"greek\">γνοφώδης</span>; v. também <span class=\"greek\">φωτεινός</span>). <span class=\"greek\">θησαυροὶ</span> <span class=\"greek\">σκ</span>. tesouros que jazem nas trevas 11:4 (Is 45:3). [<span class=\"greek\">καὶ</span> <span class=\"greek\">σκότει</span>]<span class=\"greek\">ν̣ο̣ῦ̣</span> [<span class=\"greek\">τόπου</span>] AcPl Ha 3, 19. De cor <span class=\"greek\">ἔνδυμα</span> uma veste escura ApcPt 6:21.—DELG s.v. <span class=\"greek\">σκότος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0326-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκοτία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκοτία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (cf. o verbete precedente e os três seguintes; Apollon. Rhod. 4, 1698; Anth. 8, 187; 190; Sb 6648, 4; PGM 4, 2472; Job 28:3; Mi 3:6; Is 16:3; TestSol 13:5 D; TestJob 43:6; SibOr 5, 349; Tat. 13, 4)</p><p class=\"entry-text\">① estado de privação de luz, escuridão, trevas. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:17</a>. <span class=\"greek\">σκοτίας</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">οὔσης</span> enquanto ainda estava escuro 20:1. Talvez 12:35b (v. 2). Metaf. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">σκ</span>. <span class=\"greek\">λέγειν</span> (<span class=\"greek\">εἰπεῖν</span>) <span class=\"greek\">τι</span> dizer algo no escuro, i.e., em segredo (op. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">φωτί</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:3</a> (v. HGrimme, BZ 23, ’35, 258–60).</p><p class=\"entry-text\">② obscurecimento da mente ou do espírito, trevas, extensão fig. de 1, da ignorância em assuntos morais e religiosos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:16</a> v. l. (v. Is 9:1). Esp. no uso joanino como categoria que abrange tudo quanto está em inimizade com Deus, terrestre e demoníaco <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:5ab</a>; 8:12; 12:35a; talvez também 35b (v. 1), 46; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">1J 1:5</a>; 2:8f, 11abc.—HBakotin, De Notione Lucis et Tenebrarum in Ev. Jo. ’43.—DELG s.v. <span class=\"greek\">σκότος</span> A 1. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0326-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκοτίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκοτίζω</span> (<span class=\"greek\">σκότος</span>; desde Polyb. 12, 15, 10; TestSol; Test12Patr na voz at.), em nossa lit., bem como na LXX; Mel., P. 97, 742 (não se encontra em En, EpArist, Philo, Joseph.), somente pass. <span class=\"greek\">σκοτίζομαι</span>: fut. 3 sg. <span class=\"greek\">σκοτισθήσεται</span>; 1 aor. <span class=\"greek\">ἐσκοτίσθην</span>; perf. <span class=\"greek\">ἐσκότισμαι</span>, part. <span class=\"greek\">ἐσκοτισμένος</span>.</p><p class=\"entry-text\">① estar/tornar-se escuro, ser obscurecido., lit. (Cleomedes [II d.C.] 2, 4 p. 188, 18; 24 [HZiegler 1891]) do sol que, em tempos de tribulação, perde seu fulgor (Eccl 12:2; Is 13:10) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:24</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:12</a>; 9:2 v.l. Do obscurecimento do sol por ocasião da morte de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:45</a> v.l.</p><p class=\"entry-text\">② estar/tornar-se interiormente obscurecido, extensão fig. de 1, do órgão da percepção espiritual e moral (Polyb. 12, 15, 10 Bütt.-W. v.l.=566 Fgm. 124b, 10 Jac. no texto [a pass. de obscurecimento moral]; Plut., Mor. 1120e; TestReub 3:8, TestLevi 14:4, Gad 6:2 <span class=\"greek\">τὸν</span> <span class=\"greek\">νοῦν</span>): entre politeístas <span class=\"greek\">ἐσκοτίσθη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀσύνετος</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">καρδία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:21</a>. <span class=\"greek\">σκοτισθήτωσαν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ὀφθαλμοὶ</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">βλέπειν</span> 11:10 (Ps 68:24). <span class=\"greek\">σκοτίζεσθαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">διάνοιαν</span> estar obscurecido no entendimento 2 Cl 19:2; cf. <span class=\"greek\">ἐσκοτωμένοι</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">διανοίᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:18</a> v.l.—DELG s.v. <span class=\"greek\">σκότος</span> D 5. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0326-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκότος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκότος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (como palavra masc. Hom. et al. e assim nos escritores áticos [EFraenkel, ZVS 43, 1910, 195ff; <span class=\"greek\">σκότος</span> e <span class=\"greek\">φῶς</span>], bem como Jos., Ant. 19, 216; 217; como neut. Pind. et al. e no grego helenístico ger., também na LXX [Thackeray p. 159]; pseudepígr.; Philo; Jos., Bell. 6, 140, Ant. 1, 27; apolog.; PWarr 21, 25; 30 [III d.C.].—B-D-F §51, 2; Mlt-H. 127. Somente em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:18</a> aparece <span class=\"greek\">ὁ</span> <span class=\"greek\">σκ</span>. como v.l. no t.r.) ‘escuridão’</p><p class=\"entry-text\">① escuridão, trevas, lit., da escuridão nas profundezas do mar B 10:10. De nuvens escuras ApcPt 10:25. Do obscurecimento do sol (<span class=\"greek\">σκότος</span> por ocasião da morte de Ésquilo, segundo Aristoph.: Ael. Aristid. 32, 32 K.=12 p. 145 D. Por ocasião da morte de Alexandre <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">σκότος</span>: Ps.-Callisth. 3, 33, 26. Outros HUsener, RhM n.s. 55, 1900, 286f) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:45</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:44</a>; GPt 5:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:20</a> (Jo 3:4: aqui <span class=\"greek\">σκ</span>. significa ‘portador de trevas’; v. 4, fim). Da escuridão do caos (Gen 1:2; Mel., P. 82, 611; Theoph. Ant. 1, 6 [p. 70, 19]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:6</a>. Das trevas da inexistência 1 Cl 38:3 (Sb 8960, 19 [epigrama funerário I a.C.] <span class=\"greek\">σκότους</span> <span class=\"greek\">πύλας</span>); JosAs 8:10 <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σκότους</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span>). Das trevas do lugar de punição, muito afastado do reino celestial (Philo, Exsecr. 152 <span class=\"greek\">βαθὺ</span> <span class=\"greek\">σκότος</span>. Cf. Wsd 17:20; PsSol 14:9.—<span class=\"greek\">σκ</span>. <span class=\"greek\">κ</span>. <span class=\"greek\">βόρβορος</span> ‘trevas e lama’ aguardam os que são infiéis aos Mistérios de Elêusis, Ael. Aristid. 22, 10 K.=19 p. 421 D. Das trevas da morte e do mundo inferior em Hom. e nos tragediógrafos. Como domínio de espíritos malignos PGM 36, 138; Theoph. Ant. 2, 7 [p. 110, 5]) <span class=\"greek\">τὸ</span> <span class=\"greek\">σκ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐξώτερον</span> as trevas exteriores <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:12</a>; 22:13; 25:30 (também ApcEsdr 4:37 p. 29, 16 Tdf.; cf. Vi. Aesopi W 31 P., onde Esopo aconselha um homem: <span class=\"greek\">ῥῖψον</span> <span class=\"greek\">αὐτὴν</span> [sua esposa] <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σκότος</span>.—RTaylor, Theology 33, ’42, 277–83). Também <span class=\"greek\">ὁ</span> <span class=\"greek\">ζόφος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σκότους</span> (<span class=\"greek\">ζόφος</span> 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:17</a>; Jd 13.—Da escuridão em que vivem os cegos (Soph., Oed. R. 419; Eur., Phoen. 377; 1534; Dt 28:29) com <span class=\"greek\">ἀχλύς</span> (q.v. 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:11</a>. [<span class=\"greek\">διὰ</span> <span class=\"greek\">τὸ</span>] <span class=\"greek\">σκότος</span> <span class=\"greek\">ἀφα̣</span>[<span class=\"greek\">νής</span>] despercebido por causa da escuridão AcPl Ha 3, 27 (outras restituições sugeridas no apar.).</p><p class=\"entry-text\">② o estado daquilo que é desconhecido, trevas, fig. <span class=\"greek\">τὰ</span> <span class=\"greek\">κρυπτὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σκότους</span> as coisas que estão escondidas nas trevas e, portanto, não são conhecidas de ninguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:5</a>.</p><p class=\"entry-text\">③ o estado de trevas espirituais ou morais, trevas, do obscurecimento pelo pecado, do estado dos incrédulos e dos ímpios, op. <span class=\"greek\">φῶς</span> (Herm. Wr. 7, 2a; Philo, Det. Pot. Ins. 101, Somn. 2, 39; TestLevi 19:1; TestNapht 2:10; OdeSol 11:19; TestAbr B 7 p. 111, 22 [Stone p. 70]; TestJob 43:6; JosAs 15:13; Mel., P. 68, 491; Orig., C. Cels. 6, 67, 6.—V. <span class=\"greek\">σκότος</span> como termo gnóstico Iren. 1, 4, 2 [Harv. I 36, 2]; Hippol., Ref. 10, 16, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:16</a> (Is 9:1; v. <span class=\"greek\">σκοτία</span>); 6:23b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 26:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:4f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">1J 1:6</a>; 1 Cl 59:2; B 14:7 (Is 42:7); 18:1; AcPl Ha 8, 32//BMM verso 4. Op. <span class=\"greek\">δικαιοσύνη</span> B 5:4. Cf. 14:5f. Com <span class=\"greek\">σκιὰ</span> <span class=\"greek\">θανάτου</span> (<span class=\"greek\">σκιά</span> 2b) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.79\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:79</a> (escólio sobre Soph., El. 1079 p. 149 P. <span class=\"greek\">ἐν</span> <span class=\"greek\">σκότει</span> <span class=\"greek\">γενέσθαι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θανάτου</span>. Para <span class=\"greek\">σκότος</span>=trevas da morte cf. Plut., Mor. 296ab, um juramento ‘pelo <span class=\"greek\">σκότος</span> junto ao carvalho, onde os homens de Priene haviam sido mortos em tão grande número’; v. também New Docs 4, 149).—Os pecados são <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔργα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σκότους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:11</a>.—Sobre <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐξουσία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σκότους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.53\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:53</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:13</a> v. <span class=\"greek\">ἐξουσία</span> 6. Sobre <span class=\"greek\">οἱ</span> <span class=\"greek\">κοσμοκράτορες</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σκότους</span> <span class=\"greek\">τούτου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:12</a> v. <span class=\"greek\">κοσμοκράτωρ</span>.—Em sentido relacionado, e em contraste com <span class=\"greek\">φῶς</span>, <span class=\"greek\">σκότος</span> tem o sentido</p><p class=\"entry-text\">④ portador/vítima/instrumento de trevas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:23a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:8</a> (v. KKuhn, NTS 7, ’61, 339f [Qumran]). V. também 3 acima.—B. 61. DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0326-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκοτόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκοτόω</span> (v. <span class=\"greek\">σκότος</span>; Soph., Hippocr., Pla. et al.; POxy 1854, 3; LXX, Test12Patr) pass.: 1 aor. <span class=\"greek\">ἐσκοτώθην</span>; part. perf. <span class=\"greek\">ἐσκοτωμένος</span>; prim. ‘fazer ficar escuro, escurecer’, em nossa lit. somente pass. com função intr.</p><p class=\"entry-text\">① estar/tornar-se obscurecido., lit. <span class=\"greek\">ἐσκοτώθη</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἥλιος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀήρ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:2</a> (cf. Job 3:9). Do reino da ‘Besta’ 16:10.</p><p class=\"entry-text\">② estar/tornar-se obscurecido na mente, extensão fig. de 1 (escólio sobre Nicander, Alexiphar. 27 <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐσκοτωμένοις</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">μέθῃ</span>; TestDan 2:4 <span class=\"greek\">σκ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">διάνοιαν</span>) <span class=\"greek\">διάνοια</span> <span class=\"greek\">ἐσκοτωμένη</span> entendimento obscurecido 1 Cl 36:2. <span class=\"greek\">ἐσκοτωμένος</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">διανοίᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:18</a>.—DELG s.v. <span class=\"greek\">σκότος</span> D 1. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0326-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκύβαλον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκύβαλον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> material inútil ou indesejável sujeito a descarte, refugo, lixo (em vários sentidos, ‘excremento, esterco, lixo, restos de cozinha’: Plut. et al.; PSI 184, 7; PRyl 149, 22; PFay 119, 7; Sir 27:4; Philo, Sacr. Abel. 109; 139; Jos., Bell. 5, 571; SibOr 7, 58.—<span class=\"greek\">τὰ</span> <span class=\"greek\">σκύβαλα</span> especif. de excremento humano: Artem. 1, 67 p. 61, 23; 2, 14 p. 108, 21; Jos., Bell. 5, 571 [cf. Epict., Fgm. Stob. 19 <span class=\"greek\">ἀποσκυβαλίζω</span>].—MDibelius, Hdb. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:8</a>) <span class=\"greek\">πάντα</span> <span class=\"greek\">ἡγεῖσθαι</span> <span class=\"greek\">σκύβαλα</span> considerar tudo lixo/porcaria <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:8</a> (cf. AcPl Ha 2, 23; Spicq. s.v. “para transmitir a crueza do grego … : ‘É tudo merda’.”).—DELG. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0326-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σκύθης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino; etnônimo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σκύθης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> o cita, habitante da região do mar Negro (Hes., Hdt. et al.; inscr., LXX, Philo, Joseph.), frequentemente considerado o protótipo da falta de refinamento ou da selvageria (costumes grosseiros são satirizados Aristoph., Lysist. 451ff, Thesm. 1017; cf. Cicero, In Pis. 8, Nat. Deor. 2, 34, 88; Seneca, In Troad. 1104; 2 Macc 4:47; 3 Macc 7:5) com <span class=\"greek\">βάρβαρος</span> (Philostrat., Ep. 5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:11</a>.—THermann, Barbar u. Sk.: ThBl 9, 1930, 106; WKnox, St. Paul and the Church of the Gentiles ’39, 175 com nota 4; TRice, The Scythians ’57; Reader, Polemo 383; OEANE IV 503–5.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0326-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυθρωπία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκυθρωπία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (hapax leg.; <span class=\"greek\">σκυθρωπός</span> de <span class=\"greek\">σκυθρός</span> ‘carrancudo’ e <span class=\"greek\">ὤψ</span> ‘rosto’) uma tristeza que dá aspecto sombrio ao rosto de alguém, tristeza <span class=\"greek\">ἐξῆλθεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Παῦλος</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">μεγάλης</span> <span class=\"greek\">σκυθρωπίας</span> Paulo saiu com profunda tristeza AcPl Ha 7, 36. V. o verbete seguinte.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0326-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκυθρωπός</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκυθρωπός</span> , (<span class=\"greek\">ή</span>), <span class=\"greek\">όν</span> (cf. <span class=\"greek\">σκυθρωπία</span>; Aeschyl., Hippocr., et al.; Plut., Mor. 139f; PGM 13, 259; Cat. Cod. Astr. XII 125, 14 numa lista de características pessoais negativas; LXX; TestSol; TestSim 4:1; GrBar 16:1; Philo; Jos., Ant. 6, 229) relativo a ter uma expressão que sugere abatimento ou tristeza, triste, sombrio, carrancudo, escuro (X., Mem. 2, 7, 12; Menand., Epitr. 260 S. [84 Kö.]; Jos., Bell. 1, 80) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:17</a>.—Metaf. de vestes escuras, que refletem o estado de espírito de quem as usa <span class=\"greek\">σκυθρωπότερα</span> <span class=\"greek\">ἱμάτια</span> vestes mais escuras AcPl Ha 2, 16.—DELG s.v. <span class=\"greek\">σκύζομαι</span>; Frisk s.v. <span class=\"greek\">σκυδμαίνω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0326-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σκύλλω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σκύλλω</span> part. perf. pass. <span class=\"greek\">ἐσκυλμένος</span> (Aeschyl. et al.; inscr., pap.) orig. ‘esfolar, tirar a pele’.</p><p class=\"entry-text\">① fatigar, molestar (Herodian 7, 3, 4; UPZ 110, 25 [164 a.C.] <span class=\"greek\">σκύλλεσθαι</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">μετρίως</span>; En 104:5) pass. <span class=\"greek\">ἐσκυλμένοι</span> abatidos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:36</a>.</p><p class=\"entry-text\">② perturbar, importunar, incomodar <span class=\"greek\">τινά</span> alguém. At. (TestAbr B 2 p. 107, 2 [Stone p. 62]; PTebt 421, 11; POxy 295, 5; Sb 4317, 22) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:49</a>.</p><p class=\"entry-text\">③ incomodar-se (por interessar-se por algo) (cf. pass. POxy 1669, 13 <span class=\"greek\">σκύληθι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">ἐνθάδε</span>; 123, 10; 941, 3) méd. <span class=\"greek\">μὴ</span> <span class=\"greek\">σκύλλου</span> não te incomodes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:6</a> (cf. a at. <span class=\"greek\">μὴ</span> <span class=\"greek\">σκύλλε</span> <span class=\"greek\">ἑατήν</span> POxy 295, 5; v. Rob. 807).—DELG. M-M.</p></section></article>"};
